import{_ as a,o as s,a as i,b as n}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"调试接口","link":"/api/SIMD-API/basic_api/debug_interface/debug_interface"},{"text":"关闭ASCENDC_DUMP说明","link":"/api/SIMD-API/basic_api/debug_interface/disable_ascendc_dump"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/debug_interface/disable_ascendc_dump.md","filePath":"api/SIMD-API/basic_api/debug_interface/disable_ascendc_dump.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1787050286000}'),c={name:"api/SIMD-API/basic_api/debug_interface/disable_ascendc_dump.md"};function l(p,e,t,d,_,o){return s(),i("div",null,[...e[0]||(e[0]=[n(`<div><article class="markdown-body"><h1>关闭ASCENDC_DUMP说明</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>调试接口（如本章的上板打印、异常检测接口）开启后会对算子性能产生一定影响，通常在调测阶段使用，生产环境建议关闭。ASCENDC_DUMP宏定义是控制调试接口打印的开关。</p><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><ul><li>CMake编译选项控制方式 <ul><li><p>核函数（Kernel）直调工程 修改CMakeList.txt文件中中ascendc_compile_definitions命令增加ASCENDC_DUMP=0宏定义来关闭ASCENDC_DUMP开关。示例如下：</p><div class="code-block"><pre class="highlight"><code>// 关闭所有算子的打印功能
ascendc_compile_definitions({kernel_target_name} PRIVATE
    ASCENDC_DUMP=0
)
</code></pre></div></li><li><p>自定义算子工程 修改算子工程op_kernel目录下的CMakeLists.txt文件中的add_ops_compile_options或npu_op_kernel_options，首行增加编译选项-DASCENDC_DUMP=0，关闭ASCENDC_DUMP开关，示例如下：</p><div class="code-block"><pre class="highlight"><code>// 使用add_ops_compile_options关闭所有算子的打印功能
ascendc_compile_definitions(ALL OPTIONS -DASCENDC_DUMP=0)
// 使用npu_op_kernel_options关闭所有算子的打印功能
ascendc_compile_definitions(ascendc_kernels ALL OPTIONS -DASENDC_DUMP=0)
</code></pre></div></li><li><p>宏定义控制方式 在kernel代码文件的开头位置添加#define ASCENDC_DUMP 0,示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#define ASCENDC_DUMP 0 </span><span class="c1">// 在包含头文件之前添加</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;...&quot;</span><span class="w"> </span><span class="c1">// 包含所需的头文件</span>
</code></pre></div></li></ul></li></ul></article></div>`,1)])])}const D=a(c,[["render",l]]);export{h as __pageData,D as default};
